/**
 * Signals in message VehicleEngine.
 *
 * CL250 engine values republished by rt-core from UDS DIDs 0xF40C/0xF442/0xF405/0xF411 (D-021, uds/vehicle_cl250.yaml). Scaling equals the J1979 source scaling.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_vehicle_engine_t {
    /**
     * From DID 0xF40C, (A*256+B)/4.
     *
     * Range: 0..65535 (0..16383.75 rpm)
     * Scale: 0.25
     * Offset: 0
     */
    uint16_t engine_speed;

    /**
     * From DID 0xF442, (A*256+B)/1000.
     *
     * Range: 0..65535 (0..65.535 V)
     * Scale: 0.001
     * Offset: 0
     */
    uint16_t battery_voltage;

    /**
     * From DID 0xF405, A-40.
     *
     * Range: 0..255 (-40..215 degC)
     * Scale: 1
     * Offset: -40
     */
    uint8_t coolant_temp;

    /**
     * From DID 0xF411, A*100/255 (raw byte carried unchanged).
     *
     * Range: 0..255 (0..100 %)
     * Scale: 0.392156862745098
     * Offset: 0
     */
    uint8_t throttle_pos;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t engine_speed_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t battery_voltage_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t coolant_temp_valid;

    /**
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t throttle_pos_valid;

    /**
     * 1 = the ECU answered any UDS request within the ECU-absent timeout.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t ecu_present;
};

/**
 * Signals in message SafetyRequest.
 *
 * QM requests from rt-core to the safety partition (D-072 item 4c), passed through the mailbox. E2E protects integrity only: none of these values is a safety input, and the partition applies its own authorization and invariant 6. A missing, stale or invalid frame means no request and leaves the immobilizer unlocked.
 *
 * All signal values are as on the CAN bus.
 */
struct platform_safety_request_t {
    /**
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_crc;

    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t e2_e_counter;

    /**
     * Ignition (key) state seen by rt-core power management; UNKNOWN until measured. 2 is reserved and must be treated as UNKNOWN.
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t ignition_state;

    /**
     * rt-core park mode (wake-on-motion watch, D-072 item 2); UNKNOWN until known. 2 is reserved and must be treated as UNKNOWN.
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t park_mode;

    /**
     * LOCK = the phone or park mode asks the partition to lock the starter relay; it is only a request. 2 and 3 are reserved and must be treated as NONE. There is no unlock request: unlocking is the partition's own decision (NFC, PIN, timeout).
     *
     * Range: 0..3 (0..3 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t immobilizer_lock_request;
};

